        {
            let (is_emp, g_opt) = all_g;
            is_emp.instance_id() == emp_inst@.id()
            && (match g_opt {
                None => is_emp.value(),
                Some(g) => {
                    &&& !is_emp.value()
                    &&& g.instance_id() == instance@.id()
                    &&& g.key() == page_id
                    &&& is_heap_ptr(v, g.value())
                }
            })
        }
    }
